import subprocess, os, sys
os.chdir(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
B = ("Photorealistic lifestyle photo for a family brand, bright soft natural daylight, warm cozy home, light wood floor, 35mm, everything in focus, "
     "looks like a real parent's proud Instagram photo of a handmade setup. The DIY props are made from plain brown corrugated cardboard boxes, with visible tape seams and cut edges. "
     "IMPORTANT: every paper item is plain blank bright white paper, completely empty with nothing printed or drawn on it, glued or taped perfectly flat with crisp straight edges, "
     "all four corners visible, separate from each other, not covered by hands or objects. No people's faces. No text, letters or logos anywhere, including on the boxes.")
jobs = {
 'pizza': "A child's pretend pizzeria built in a living room corner from cardboard boxes. Center: a big cardboard box turned into a pizza oven, with one blank portrait Letter sheet glued flat to its front face and a toy wooden pizza peel leaning on it. Left: a small cardboard box cash register on a low table, with one blank portrait Letter sheet glued flat on its front face. On the wall above: one long blank landscape banner strip (about 3.5 to 1 proportions) taped up as the shop sign. On the low table: one blank portrait Letter sheet lying flat as a menu, and a stack of three small flat cardboard pizza boxes each with one small blank landscape label (3:2) glued on its lid. A felt pizza on a plate, a small chef hat. A child's small hand in a striped sleeve slides the felt pizza into the oven opening from the right edge.",
 'vet': "A child's pretend vet clinic built in a playroom from cardboard boxes. Center: a tall cardboard box turned into an X-ray machine for stuffed animals, with one blank portrait Letter sheet glued flat to its front face and a plush puppy lying on a little cardboard table in front of it. Left: a cardboard box pet carrier with a cut-out door and handle, with one blank landscape half-sheet (3:2) glued flat on its side as a sign, a plush kitten peeking out. On the wall: one blank landscape half-sheet (3:2) taped up as the clinic sign. On the floor: a cardboard box medicine cabinet with two small blank landscape labels (3:2) glued on its drawers. A toy stethoscope and bandages. A child's small hand holds the toy stethoscope to the puppy from the right edge.",
 'dino': "A child's pretend dinosaur dig lab built in a living room from cardboard boxes. Center: a shallow cardboard box filled with play sand as a dig pit, with toy dinosaur skeleton bones half buried, and one blank landscape half-sheet (3:2) glued flat to its front side as a sign. Right: a cardboard box hatchery with a cut-out round window, with one blank portrait Letter sheet glued flat to its front face, toy dinosaur eggs on top. On the wall: one blank landscape half-sheet (3:2) taped up as the lab sign, and one blank portrait Letter sheet taped up as a map. Toy dinosaurs, a brush, a magnifying glass. A child's small hand brushes sand off a bone from the bottom edge.",
 'unicorn': "A child's pretend unicorn stable built in a girl's playroom from cardboard boxes. Two big cardboard boxes turned into stable stalls side by side, each with a cut-out half door, and one blank landscape half-sheet (3:2) glued flat above each door as a name sign; a plush unicorn with a rainbow mane in one stall and a plush pony in the other. Pastel bunting, a little hay bale, toy carrots in a basket. On the wall: one blank portrait Letter sheet taped up as a menu. On the floor in front: a cardboard box treat trough with one small blank landscape label (3:2) glued on its front. A child's small hand brushes the unicorn mane from the right edge.",
 'halloween': "A child's pretend Halloween potion shop built at a low table from cardboard boxes, autumn evening, warm fairy lights. Center: a cardboard box turned into a big cauldron stand with one blank portrait Letter sheet glued flat to its front face, a black toy cauldron on top with a wooden spoon. Left: a cardboard box shelf of little glass jars of colored water, with three small blank landscape labels (3:2) glued flat along its front edge. On the wall: one blank landscape half-sheet (3:2) taped up as the shop sign, and two blank portrait sheets taped side by side as posters. Mini pumpkins, a purple witch hat, plastic spiders. A child's small hand stirs the cauldron from the right edge.",
}
only = sys.argv[1:] or list(jobs)
for name in only:
    if os.path.exists(f'r3/{name}.png'): continue
    r = subprocess.run([sys.executable, 'gen.py', 'gemini-3-pro-image', f'r3/{name}.png', jobs[name] + ' ' + B], capture_output=True, text=True)
    print(name, r.stdout.strip()[-200:], r.stderr.strip()[-300:], flush=True)
print('ALLDONE')
